#!/bin/sh
set -eu

crate_dir=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)
repository_dir=$(CDPATH= cd -- "$crate_dir/../.." && pwd)
formal_dir="$repository_dir/formal/dclutch-semantics"
generated=$(mktemp "${TMPDIR:-/tmp}/dclutch-direct-program-v2.XXXXXX")
trap 'rm -f "$generated"' EXIT HUP INT TERM

(
  cd "$formal_dir"
  lake build DClutchSemantics.DirectProgramV2
  lake env lean EmitDirectProgramV2Rust.lean
  lake env lean --run EmitDirectProgramV2Rust.lean > "$generated"
)

test "$(sed -n '1p' "$generated")" = \
  '// @generated by formal/dclutch-semantics/EmitDirectProgramV2Rust.lean; do not edit.'
grep -q '^pub const DIRECT_PROGRAM_V2_BYTES: usize = 856;$' "$generated"
grep -q '^pub const DIRECT_PROGRAM_V2_SCALARS: u16 = 41;$' "$generated"
grep -q '^pub const DIRECT_PROGRAM_V2_IDENTITIES: u16 = 4;$' "$generated"
rustfmt --edition 2024 "$generated"
cmp "$generated" "$crate_dir/src/generated.rs"
